sql:
SELECT dose_val_rx, dose_unit_rx 
FROM prescriptions 
WHERE subject_id = 23224 AND hadm_id = 117806 AND drug = 'Clonazepam';

SELECT DISTINCT drug 
FROM prescriptions 
WHERE subject_id = 31038 AND hadm_id = 174978 AND drug IN ('Zolpidem Tartrate', 'Diazepam', 'Midazolam', 'Metoclopramide');

SELECT COUNT(*) AS narcotics_count 
FROM prescriptions 
WHERE hadm_id = 145249 AND LOWER(drug) IN ('hydromorphone (dilaudid)', 'tramadol (ultram)');

SELECT COUNT(*) AS medication_count 
FROM prescriptions 
WHERE subject_id = 24687 AND hadm_id = 145249;

SELECT diagnosis 
FROM admissions 
WHERE hadm_id = 120799 AND subject_id = 78097;

SELECT COUNT(*) AS medication_count 
FROM prescriptions 
WHERE subject_id = 78097 AND hadm_id = 120799;

SELECT COUNT(*) AS cp_count 
FROM cptevents 
WHERE subject_id = 18363 AND hadm_id = 117258;

SELECT DISTINCT drug 
FROM prescriptions 
WHERE subject_id = 30977 AND hadm_id = 183457 AND LOWER(drug) LIKE '%pain%';

SELECT DISTINCT drug 
FROM prescriptions 
WHERE subject_id = 80041 AND hadm_id = 102677 AND LOWER(drug) LIKE '%chest pain%';

SELECT COUNT(*) AS vicodin_count 
FROM prescriptions 
WHERE subject_id = 80041 AND hadm_id = 102677 AND LOWER(drug) = 'vicodin';

SELECT startdate AS tablet_time 
FROM prescriptions 
WHERE subject_id = 2589 AND hadm_id = 113195 AND LOWER(drug) LIKE '%tablet%';

SELECT MIN(startdate) AS first_coumadin_date 
FROM prescriptions 
WHERE hadm_id = 192833 AND LOWER(drug) = 'coumadin';
